21	MEMORY
22	{
23	  flash (rx) : ORIGIN = 0x12010000, LENGTH = 16M
24	  sram (rwx) : ORIGIN = 0x20000000, LENGTH = 512K
25	  psram (rwx) : ORIGIN = 0x60000000, LENGTH = 8M
