27	
28	OUTPUT_ARCH(arm)
29	EXTERN(_vectors)
30	/* Provide __Vectors alias for SystemInit() compatibility */
31	__Vectors = _vectors;
32	ENTRY(_stext)
33	
34	SECTIONS
35	{
36	    /* Discard build-id to ensure vectors start at flash base */
37	    /DISCARD/ : {
38	        *(.note.gnu.build-id)
39	    }
40	
41	    .text : {
42	        _stext = ABSOLUTE(.);
43	        /* Ensure vector table is properly aligned (must be at flash start) */
44	        . = ALIGN(512);
45	        KEEP(*(.vectors))
46	        /* Add padding after vectors to match SDK layout */
47	        . = ALIGN(4);
48	        *(.text .text.*)
49	        *(.fixup)
50	        *(.gnu.warning)
51	        *(.rodata .rodata.*)
52	        *(.gnu.linkonce.t.*)
53	        *(.glue_7)
54	        *(.glue_7t)
55	        *(.got)
56	        *(.gcc_except_table)
57	        *(.gnu.linkonce.r.*)
58	
59	        KEEP(*(.init))
60	        KEEP(*(.fini))
61	
62	        /* Section information for finsh shell */
63	        . = ALIGN(4);
64	        __fsymtab_start = .;
65	        KEEP(*(FSymTab))
66	        __fsymtab_end = .;
67	
68	        . = ALIGN(4);
69	        __vsymtab_start = .;
70	        KEEP(*(VSymTab))
