76	        __rt_utest_tc_tab_end = .;
77	
78	        /* Section information for initial */
79	        . = ALIGN(4);
80	        __rt_init_start = .;
81	        KEEP(*(SORT(.rti_fn*)))
82	        __rt_init_end = .;
83	
84	        . = ALIGN(4);
85	        __sifli_reg_start__ = .;
86	        KEEP(*(SORT(.sifli_reg*)))
87	        __sifli_reg_end__ = .;
88	
89	        . = ALIGN(4);
90	        __bt_sifli_reg_start__ = .;
91	        KEEP(*(SORT(.bt_sifli_reg*)))
92	        __bt_sifli_reg_end__ = .;
93	
94	        /* Section information for modules */
95	        . = ALIGN(4);
96	        __rtmsymtab_start = .;
97	        KEEP(*(RTMSymTab))
98	        __rtmsymtab_end = .;
99	
100	        /* Section information for LCD drivers */
101	        . = ALIGN(4);
102	        LcdDriverDescTab_start = .;
103	        KEEP(*(LcdDriverDescTab))
104	        LcdDriverDescTab_end = .;
105	
106	        KEEP(*(.eh_frame*))
107	        _etext = ABSOLUTE(.);
108	    } > flash
